INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("青空の下で謁見", 10118, 2, 0, "ペコリーヌとの出会い", 20063115, 1, "フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。", 5118061, 40, 8, 2834, "フリーマーケット会場", 7, 91002);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("未来の騎空団\nマスコット？", 10118, 2, 0, "マホとの出会い", 20063115, 1, "ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。", 5118062, 40, 8, 2835, "フリーマーケット会場", 7, 91002);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("お嬢さまからの\n緊急依頼", 10118, 2, 0, "アキノとの出会い", 20063115, 1, "ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。", 5118063, 40, 8, 2837, "ランドソル市街地", 7, 91002);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("黄金色の悩みごと", 10118, 2, 0, "ジュンとの出会い", 20063115, 1, "ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。", 5118064, 40, 8, 4108402, "フリーマーケット会場", 18, 91002);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("白熱！　格闘大会！", 10118, 2, 0, "カオリとの出会い", 20063115, 1, "フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？", 5118065, 40, 8, 4107402, "フリーマーケット会場", 18, 91002);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("祭り太鼓はオーエドの華", 10118, 2, 1, "ニノンとの出会い", 20063115, 1, "太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。", 5118066, 40, 8, 9000227, "オーエド町", 16, 91002);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("人気者は遅れて\nやってくる", 10118, 3, 0, "スズナとの出会い", 20063115, 1, "ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？", 5118067, 40, 8, 2101181, "フリーマーケット会場", 19, 91002);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("巫女・ミーツ・魔法少女", 10118, 3, 0, "ナナカとの出会い", 20063115, 1, "ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？", 5118068, 40, 8, 4109402, "ランドソル市街地", 18, 91002);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ネズ耳は二度なくなる", 10118, 3, 0, "キャル＆コッコロとの出会い", 20063115, 1, "ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……", 5118069, 40, 8, 4305402, "フリーマーケット会場", 18, 91002);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("この出会いにカンパイ！", 10118, 3, 0, "ユカリとの出会い", 20063115, 1, "街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。", 5118070, 40, 8, 4101402, "ランドソル市街地", 18, 91002);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("陰陽アンサンブル", 10118, 3, 0, "アオイとの出会い", 20063115, 1, "ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……", 5118071, 40, 8, 4106402, "ランドソル市街地", 18, 91002);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("運試し十番勝負！", 10118, 3, 1, "シノブとの出会い", 20063115, 1, "ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。", 5118072, 40, 8, 2836, "フリーマーケット会場", 7, 91002);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("彼女たちの新たな日常", 10118, 1, 0, "オープニング", 20063115, 0, 0, 5118600, 0, 0, 0, 0, 0, 0);
